            JSONObject()
                .put("unapplied", JSONArray(value.unapplied.map { json(it) }))

        private fun TokamakValue.asShowInForeground(): ShowInForeground {
            val json = json()
            return when {
                json is Boolean -> ShowInForeground.All(this.boolean())
                json is JSONObject -> asForegroundPresentation()
                else -> throw mismatch("ShowInForeground")
            }
        }

        private fun json(value: ShowInForeground): Any =
            when (value) {
                is ShowInForeground.All -> value.value
                is ShowInForeground.ForegroundPresentation -> json(value)
            }

        private fun TokamakValue.asStyle(): Style =
            when (this["type"].string()) {
                "bigPicture" -> asBigPicture()
                "bigText" -> asBigText()
                "inbox" -> asInbox()
                "messaging" -> asMessaging()
                else -> throw mismatch("Style")
            }

        private fun json(value: Style): JSONObject =
            when (value) {
                is Style.BigPicture -> json(value).put("type", "bigPicture")
                is Style.BigText -> json(value).put("type", "bigText")
                is Style.Inbox -> json(value).put("type", "inbox")
                is Style.Messaging -> json(value).put("type", "messaging")
            }

        private fun TokamakValue.asStyleMessage(): StyleMessage =
            StyleMessage(
                text = this["text"].string(),
                at = this["at"].long(),
                sender = this["sender"].nullable { it.string() },
            )

        private fun json(value: StyleMessage): JSONObject =
            JSONObject()
                .put("text", value.text)
                .put("at", value.at)
                .putOpt("sender", value.sender)

        private fun TokamakValue.asSubscription(): Subscription =
            Subscription(
                service = this["service"].enum(PushService.entries),
                fid = this["fid"].string(),
            )

        private fun json(value: Subscription): JSONObject =
            JSONObject()
                .put("service", value.service.name)
                .put("fid", value.fid)

        private fun TokamakValue.asTrigger(): Trigger {
            val json = json()
            return when {
                json is JSONObject && json.has("at") -> asAtTrigger()
                json is JSONObject && json.has("on") -> asDateTrigger()
                json is JSONObject && json.has("every") -> asEveryTrigger()
                else -> throw mismatch("Trigger")
            }
        }

        private fun json(value: Trigger): Any =
            when (value) {
                is Trigger.AtTrigger -> json(value)
                is Trigger.DateTrigger -> json(value)
                is Trigger.EveryTrigger -> json(value)
            }

        private fun TokamakValue.asUnapplied(): Unapplied =
            Unapplied(
                channel = this["channel"].string(),
                fields = this["fields"].list { it.string() },
            )

        private fun json(value: Unapplied): JSONObject =
            JSONObject()
                .put("channel", value.channel)
                .put("fields", JSONArray(value.fields))

        private fun TokamakValue.asVibration(): Vibration {
            val json = json()
            return when {
                json is Boolean -> Vibration.Enabled(this.boolean())
                json is JSONArray -> Vibration.Pattern(this.list { it.long() })
                else -> throw mismatch("Vibration")
            }
        }

        private fun json(value: Vibration): Any =
            when (value) {
                is Vibration.Enabled -> value.value
                is Vibration.Pattern -> JSONArray(value.value)
            }
    }
}
